from pathlib import Path
p = Path("app/src/main/java/com/shadowai/app/MainActivity.kt")
data = p.read_text(encoding="utf-8")
start = data.index("private fun setupSuggestions()")
end = data.index("private fun checkAndRequestAudioPermission")
replacement = """private fun setupSuggestions() {\n        val activeProvider = adminRepository.getActiveProvider()?.let { providerRepo.getProvider(it) }\n        val caps = activeProvider?.capabilities ?: emptyList()\n        val hasImageGen = caps.contains(com.shadowai.app.providers.Capability.IMAGE_GEN)\n        val suggestions = buildList {\n            if (hasImageGen) add(\"\\uD83D\\uDDBC Generate Image\" to \"ACTION_PIXAI\")\n            add(\"\\uD83E\\uDDD8\\u200D\\u2642\\uFE0F Write Story\" to \"ACTION_NOVELAI\")\n            add(\"\\u260E Call...\" to \"call \")\n            add(\"\\u2709 Send SMS\" to \"sms \")\n            add(\"\\u25B6 Media Toggle\" to \"play\")\n            add(\"\\uD83C\\uDFE0 Go Home\" to \"home\")\n            add(\"\\uD83D\\uDD0E Inspect Screen\" to \"inspect screen\")\n            add(\"\\u2699 System Status\" to \"status\")\n        }\n        suggestionsRecyclerView.layoutManager = LinearLayoutManager(this, LinearLayoutManager.HORIZONTAL, false)\n        suggestionsRecyclerView.adapter = SuggestionsAdapter(suggestions) { command ->\n            when (command) {\n                \"ACTION_PIXAI\" -> launchPixAi()\n                \"ACTION_NOVELAI\" -> launchNovelAi()\n                else -> {\n                    inputText.setText(command)\n                    if (!command.endsWith(\" \\")) {\n                        processQuery(command)\n                    } else {\n                        inputText.requestFocus()\n                        inputText.setSelection(command.length)\n                    }\n                }\n            }\n        }\n    }\n\n"""
new_data = data[:start] + replacement + data[end:]
p.write_text(new_data, encoding="utf-8")
